BEGIN;
CREATE OR REPLACE FUNCTION public.privacy_finalize_membership() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE cid uuid;m public.loyalty_memberships;doc text;
BEGIN
 IF NEW.status<>'ORDER_CREATED' OR OLD.status='ORDER_CREATED' THEN RETURN NEW; END IF;
 doc=NEW.order_payload->'legal'->>'version';
 IF coalesce(doc NOT IN ('2026-10-19.1','2026-11-11.1'),true) OR (NEW.order_payload->'legal'->>'acknowledged') IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'LEGAL_VERSION_REQUIRED'; END IF;
 SELECT customer_id INTO cid FROM public.orders WHERE id=NEW.order_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('privacy:'||cid::text,0));
 INSERT INTO public.privacy_events(customer_id,checkout_id,event_type,document_version) VALUES(cid,NEW.id,'order_acknowledged',doc);
 SELECT * INTO m FROM public.loyalty_memberships WHERE customer_id=cid FOR UPDATE;
 IF (doc='2026-11-11.1' OR NEW.order_payload->>'loyaltyOptIn'='true') AND (m.revoked_at IS NULL OR NEW.created_at>m.revoked_at) THEN
  -- Existing active consent is not renewed merely by checkout, browsing or a duplicate.
  IF NOT coalesce(m.status='active' AND m.expires_at>now(),false) THEN
   IF m.customer_id IS NOT NULL AND m.expires_at<=now() THEN INSERT INTO public.loyalty_ledger(customer_id,program_id,operation_type,progress_delta,reward_delta,idempotency_key,metadata)
 SELECT l.customer_id,l.program_id,'MANUAL_ADJUSTMENT',(-sum(l.progress_delta))::integer,(-sum(l.reward_delta))::integer,
 'privacy-close:'||l.customer_id::text||':'||membership_row.version::text||':'||l.program_id::text||'',
 jsonb_build_object('reason','membership_terminated','membershipVersion',membership_row.version)
 FROM public.loyalty_ledger l JOIN public.loyalty_memberships membership_row ON membership_row.customer_id=l.customer_id
 WHERE l.customer_id=cid GROUP BY l.customer_id,l.program_id,membership_row.version
 HAVING sum(l.progress_delta)<>0 OR sum(l.reward_delta)<>0 ON CONFLICT(idempotency_key) DO NOTHING; END IF;
   INSERT INTO public.loyalty_memberships(customer_id,status,consented_at,expires_at,document_version) VALUES(cid,'active',now(),now()+interval '24 months',doc)
   ON CONFLICT(customer_id) DO UPDATE SET status='active',version=public.loyalty_memberships.version+1,consented_at=now(),expires_at=now()+interval '24 months',document_version=doc,last_activity_key=NULL;
   INSERT INTO public.privacy_events(customer_id,checkout_id,event_type,document_version) VALUES(cid,NEW.id,'loyalty_consented',doc);
  END IF;
 END IF;
 RETURN NEW;
END $$;

INSERT INTO public.legal_document_archive(version,slug,body,sha256) VALUES('2026-11-11.1','offer','ИП Менделева Любовь Валентиновна, УНП 391085703. Республика Беларусь, Витебская область, г. Дубровно, ул. Почтовая, 6. Телефон: +375 33 376-26-99.
Сайт: https://project-dubrovno.store/.
Заказы принимаются ежедневно с 10:00 до 22:00 по времени Беларуси. Продукция, состав, цены и доступность указаны в каталоге и открытых карточках товаров. Цены — в белорусских рублях.
Самовывоз: г. Дубровно, ул. Почтовая, 6. Оплата в заведении — наличными или банковской картой. Курьер принимает только наличные; терминала у курьера нет. Онлайн-оплата на сайте не производится.
Доставка собственными сотрудниками платная, минимальной суммы заказа нет. Территория — г. Дубровно и прилегающие населённые пункты на расстоянии до 5 км от центра города по дорогам общего пользования. Стоимость доставки рассчитывает и согласовывает администратор. До согласования на сайте указана стоимость товаров без доставки. При вопросах о зоне свяжитесь с заведением до заказа.
Нажимая «Оформить заказ», покупатель принимает изложенные условия и оформляет заказ. Для вошедшего пользователя используется ранее подтверждённый телефон личного кабинета; остальным покупателям необходимо подтвердить телефон через Telegram. Время готовности сообщается после получения заказа через Telegram; время доставки уточняется при согласовании исполнения. Подтверждение телефона и сообщение о создании не являются сообщением о готовности.
Для изменения, отмены, уточнения срока или предъявления претензии свяжитесь с заведением по указанному телефону; письменные обращения принимаются по адресу ИП. Права потребителя, порядок отказа, возврата оплаты и ответственность определяются законодательством Республики Беларусь. Эти условия не уменьшают обязательных гарантий и не устанавливают общего запрета возврата оплаты за непереданную продукцию.
При чрезвычайных препятствиях, опасных дорожных условиях или официальных ограничениях приём либо исполнение заказов может быть временно ограничено с уведомлением покупателей. Обстоятельства не признаются автоматически непреодолимой силой; по уже полученным заказам согласовываются дальнейшие действия с сохранением законных прав покупателя.
Обработка данных описана в Политике. Каждый новый онлайн-заказ подключает покупателя к акциям по номеру телефона, в том числе после предыдущего выхода. Редакция условий сохраняется вместе с оформлением.','390dd10566c2843ce7593adadf72b036c0cab4382b7c0fc23f210d1630e77634');
INSERT INTO public.legal_document_archive(version,slug,body,sha256) VALUES('2026-11-11.1','privacy','Оператор: ИП Менделева Любовь Валентиновна, УНП 391085703. Республика Беларусь, Витебская область, г. Дубровно, ул. Почтовая, 6. Телефон: +375 33 376-26-99.
Для оформления и исполнения заказа используются имя, телефон (подтверждённый через Telegram либо сверенный сотрудником при личном обращении), состав заказа, его стоимость и статус; для доставки — адрес и необходимые указания. Комментарий добровольный: не указывайте паспортные данные, банковские реквизиты и сведения о здоровье. Основание необходимых действий по заказу — заключаемый/заключённый договор; обязательный учёт ведётся на предусмотренных законодательством основаниях.
Подтверждение телефона производится через Telegram: используются предоставленный контакт, идентификатор пользователя и доступные технические сведения подтверждения, а при наличии — username. Через Telegram сообщаются сведения о статусе и готовности заказа. Это сервисные сообщения, не реклама. Telegram — внешний сервис; размещение основной БД в Беларуси не исключает передачи данных иностранному сервису. Не используйте чужой телефон или чужой контакт для подтверждения.
Данные обрабатываются на сервере и в приложении заведения; доступ сотрудников ограничивается исполнением обязанностей. Курьеры — собственные сотрудники. Данные хранятся на VDS и в резервных копиях в Беларуси по сведениям оператора; поставщик инфраструктуры — support.by (global.support.by). Договорные реквизиты и условия порученной обработки предоставляются по обращению к оператору.
Используются сбор, запись, систематизация, хранение, уточнение, использование, предоставление необходимого доступа, блокирование и удаление. Данные не используются для рекламной рассылки и не продаются рекламным партнёрам.
При оформлении нового онлайн-заказа покупатель подключается к программе лояльности по номеру телефона. Обрабатываются имя, телефон (подтверждённый через Telegram либо сверенный сотрудником при личном обращении), идентификатор участника и необходимые сведения о покупках и накоплениях. Адрес доставки не требуется для лояльности. Условия и срок указаны в правилах участия.
Согласованные целевые сроки: временные оформления — 24 часа после истечения; рабочие контакты исполненного/отменённого заказа — 30 дней после окончательного статуса при отсутствии отдельного основания; профиль лояльности — до отзыва и не дольше 24 месяцев без участия. Расчётные документы и материалы обоснованных претензий хранятся отдельно по применимым основаниям и срокам. Истечение ссылки подтверждения само по себе не означает удаления данных.
Очистка контактов заказов и охват локальных/резервных копий вводятся после проверки сохранности документов и процедур восстановления. До завершения этого этапа сроки 24 часа и 30 дней являются планом внедрения, а не заявлением об уже работающем удалении во всех системах. Информацию о фактическом хранении и запрос на прекращение обработки можно получить у оператора.
Вы вправе в предусмотренных законом случаях получить сведения об обработке и получателях, исправить неточные данные, потребовать прекращения или удаления при отсутствии оснований, отозвать согласие и обжаловать нарушения в НЦЗПД. Отзыв не прекращает обработку по самостоятельному законному основанию, например обязательный учёт расчётов. Письменные обращения — по адресу ИП; консультации — по телефону. Для электронного отзыва лояльности доступна страница /privacy/manage после подтверждения телефона. Отказ от лояльности не препятствует обычному заказу.','731cac29c97ad73c5d03f56b545e5b0b93c0ded1a3df51fe2494050544aa13da');
INSERT INTO public.legal_document_archive(version,slug,body,sha256) VALUES('2026-11-11.1','loyalty','Организатор: ИП Менделева Любовь Валентиновна, УНП 391085703. Республика Беларусь, Витебская область, г. Дубровно, ул. Почтовая, 6. Телефон: +375 33 376-26-99.
Участие бесплатное. Каждый новый онлайн-заказ подключает покупателя к акциям по подтверждённому телефону автоматически, включая повторное подключение после выхода. Участие доступно и без входа в личный кабинет. В заведении сотрудник сверяет телефон и фиксирует подключение по действующим правилам.
Покупки учитываются после оплаты и обработки продажи заведением. Подарок начисляется при достижении указанного количества; одновременно доступен не более одного подарка в каждой программе. Пока подарок не использован, новое накопление в этой программе приостановлено. На сайте подарок применяется кнопкой «Использовать подарок»: бесплатной становится одна самая дешёвая подходящая позиция в корзине. Она не начисляет прогресс. Подарок списывается при создании заказа и возвращается при его отмене. Подарки нельзя обменять на деньги. Возврат покупки может корректировать связанные начисления в пределах применимых правил и законных прав покупателя.
При добровольном выходе и отзыве согласия участие прекращается, оставшиеся подарки и незавершённые накопления аннулируются. Обычные заказы доступны. Прежние накопления не обнуляются автоматически только вследствие внедрения согласий. Если в течение 24 месяцев нет покупок, учтённых в программе, участие и оставшиеся подарки прекращаются. Этот срок не продлевается служебными повторами или синхронизацией. Новый онлайн-заказ подключает покупателя по действующим условиям. Вопросы восстановления доступа и прекращения участия решаются с организатором.
Новый онлайн-заказ возобновляет участие после выхода; прежние аннулированные накопления не восстанавливаются. Прекратить участие можно на /privacy/manage после подтверждения телефона либо обратиться к организатору.','f8fa2c6840be61a9cdedcab0606a60f3412093e6485a6dfb2bb4613294e95492');
INSERT INTO public.legal_document_archive(version,slug,body,sha256) VALUES('2026-11-11.1','consent','Оператор, получающий согласие: ИП Менделева Любовь Валентиновна, УНП 391085703. Республика Беларусь, Витебская область, г. Дубровно, ул. Почтовая, 6. Телефон: +375 33 376-26-99.
Цель — подключение и обслуживание участия в программе лояльности, учёт необходимых покупок, начисление и использование подарков. Данные: имя, телефон (подтверждённый через Telegram либо сверенный сотрудником при личном обращении), идентификатор участника, необходимые сведения о покупках и накоплениях; для связи через Telegram — идентификатор пользователя и доступный username. Адрес доставки и рекламные цели в согласие не включаются.
Действия: сбор, запись, систематизация, хранение, уточнение, использование, предоставление необходимого доступа сотрудникам, передача между сервером и приложением заведения, блокирование и удаление. Обработка автоматизированная и с участием сотрудников. Инфраструктура — support.by (global.support.by), сервер и копии в Беларуси по сведениям оператора; используется внешний сервис Telegram для подтверждения телефона и предусмотренных сервисных сообщений. Дополнительные сведения о фактических получателях и условиях предоставляются оператором по указанному контакту.
Срок: до отзыва, но не дольше 24 месяцев со дня получения согласия или последней покупки, учтённой в программе, в зависимости от более поздней даты. Продление вследствие покупки действует только при активном участии. Служебный обмен, просмотр сайта и повторная доставка одного события срок не продлевают.
Каждый новый онлайн-заказ автоматически подключает покупателя к программе по номеру телефона. После выхода следующий онлайн-заказ подключает покупателя заново. При отзыве участие, оставшиеся подарки и незавершённые накопления прекращаются. Вы можете отозвать согласие на /privacy/manage после подтверждения телефона, а также обратиться к оператору предусмотренным законом способом; отдельный рекламный отказ не требуется, рекламы нет.
Вы вправе получить информацию об обработке и получателях, требовать исправления неточностей, прекращения обработки и удаления при отсутствии оснований, обжаловать нарушения в НЦЗПД. После отзыва обработка для этой цели прекращается, необходимые удаление/блокирование и ответ выполняются в применимые законные сроки; самостоятельные основания, например обязательные документы расчётов, рассматриваются отдельно. Само внедрение новой процедуры согласия не аннулирует прежние подарки; при добровольном выходе или 24 месяцах без участия они прекращаются по правилам программы.
Оформление нового онлайн-заказа связывается с подтверждённым телефоном, временем и редакцией условий. При личном обращении сотрудник предоставляет эти сведения и условия, сверяет телефон со слов покупателя и отдельно фиксирует его добровольное согласие. Сохраняются способ получения согласия, серверное время, устройство, сведения о сотруднике и редакция документов. Telegram для этого способа не требуется. Наличие старой карточки само по себе не является согласием. Подробности — в Политике обработки персональных данных.','ec50af636c734b5831aa08bf279af34494152253f14a1cbf81000cde97f93338');
COMMIT;
